#!/usr/bin/env python3
"""
Round 190o (culprits), 8 October 2026. Needs round 189o.

Methane from oil and gas, each country (IEA Global Methane Tracker 2026).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 190o (8 October)\n\nNeeds round 189o (guards on its heading). Tiles patch round190o_tiles.py\nbeside it. No app.js?v= bump.\n\n- iea_oilgas_methane (route sitemap, tiles methane/iea_oilgas.places.geojson\n  and .boxes.json, made by tiles iea_methane.py from the owner\'s IEA Global\n  Methane Tracker 2026 downloads kept in tiles methane/iea/: by_source.csv,\n  abatement.csv, gas_prices.csv, comparison.csv). The IEA confirmed CC BY\n  4.0 by email; credit "IEA (2026), Global Methane Tracker 2026 ... modified\n  by Welcome to Your Galaxy"; no IEA logo, no embedding their interactive\n  map. 102 countries on the map\'s own shapes (Korea = KOR, Cote d\'Ivoire,\n  DR Congo aliased), 18 colourings (oil and gas total, gas, oil, satellite\n  large emitters, each reason, each production source), sextile steps.\n  The oil and gas total leaves out the satellite rows (the IEA lists them\n  apart). Abatement measures are listed per country, not summed (LDAR\n  frequencies are alternatives). Group rows (World, EU, Rest of ...), the\n  sector comparison and gas prices are in the entries window. First under\n  Methane > Emissions.\n- Global Tipping Points Report 2025 PDF attached by the owner: not used yet,\n  the owner will say where it goes.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round190o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 189o" not in h.read_text(encoding="utf-8"):
        sys.exit("round190o: round 189o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round190o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round190o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round190o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
